import {products,colours,money,imageFor,featuredGarment} from './catalogue.js';
import {commerce,createCheckout} from './commerce.js';
import {preloadVariants,showProductImage} from './product-images.js';
const warmObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){const p=products.find(p=>p.id===entry.target.dataset.id);if(p)preloadVariants(p);warmObserver.unobserve(entry.target);}}},{rootMargin:'500px'});
preloadVariants(products.find(p=>p.id===featuredGarment.productId)||products[0]);
const $=s=>document.querySelector(s),productDialog=$('#product-dialog'),bagDialog=$('#bag-dialog');let filter='All',collection='All',sort='featured',selected=null,selectedColour='black',selectedSize=null,lastTrigger=null,bag=[];const storageKey='arvyra-draft-bag-v2';
try{const raw=JSON.parse(sessionStorage.getItem(storageKey)||'[]');if(Array.isArray(raw))bag=raw.filter(l=>{const p=products.find(p=>p.id===l.id);return p&&p.colours.includes(l.colour)&&p.sizes.includes(l.size)&&Number.isInteger(l.quantity)&&l.quantity>0&&l.quantity<=10;}).slice(0,80);}catch{}
const key=l=>`${l.id}|${l.colour}|${l.size}`;function saveBag(){try{sessionStorage.setItem(storageKey,JSON.stringify(bag));}catch{}$('#bag-count').textContent=bag.reduce((n,l)=>n+l.quantity,0);}
function renderCatalogue(){warmObserver.disconnect();let list=products.filter(p=>(filter==='All'||p.type===filter)&&(collection==='All'||p.collection===collection));if(sort!=='featured')list.sort((a,b)=>sort==='low'?a.price-b.price:b.price-a.price);$('#result-count').textContent=`${list.length} styles · ${new Set(list.flatMap(p=>p.colours)).size} colour options`;
 $('#catalogue').innerHTML=list.map((p,i)=>`<article class="store-card" data-id="${p.id}"><a href="#product=${p.id}&colour=${p.colours[0]}" class="product-picture"><img src="${imageFor(p,p.colours[0])}" width="600" height="750" loading="lazy" alt="${p.name} in ${colours[p.colours[0]].name}"><span class="product-badge">${p.collection}</span></a><a href="#product=${p.id}&colour=${p.colours[0]}" class="card-title">${p.name}</a><div class="card-subline"><span>${p.type} / ${p.colours.length} colours</span><span class="card-price">${money(p.price)}</span></div><div class="card-bottom"><div class="card-swatches" role="group" aria-label="${p.name} colours">${p.colours.map(c=>`<button type="button" class="swatch" data-colour="${c}" style="--swatch:${colours[c].hex}" aria-label="${p.name} in ${colours[c].name}" aria-pressed="${c===p.colours[0]}"></button>`).join('')}</div><a class="card-shop" href="#product=${p.id}&colour=${p.colours[0]}">Choose options</a></div></article>`).join('');
 $('#catalogue').querySelectorAll('.store-card').forEach(card=>{warmObserver.observe(card);card.addEventListener('pointerenter',()=>preloadVariants(products.find(p=>p.id===card.dataset.id)),{once:true});card.addEventListener('focusin',()=>preloadVariants(products.find(p=>p.id===card.dataset.id)),{once:true});});
 $('#catalogue').querySelectorAll('[data-colour]').forEach(button=>button.addEventListener('click',()=>{const card=button.closest('.store-card'),p=products.find(p=>p.id===card.dataset.id),c=button.dataset.colour;showProductImage(card.querySelector('img'),p,c,`${p.name} in ${colours[c].name}`);card.querySelectorAll('a').forEach(a=>a.href=`#product=${p.id}&colour=${c}`);card.querySelectorAll('[data-colour]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));}
function route(){const params=new URLSearchParams(location.hash.slice(1));const p=products.find(p=>p.id===params.get('product'));if(p)openProduct(p,params.get('colour'));else if(productDialog.open)productDialog.close();}
function openProduct(p,c){preloadVariants(p);if(bagDialog.open)bagDialog.close();lastTrigger=document.activeElement;selected=p;selectedColour=p.colours.includes(c)?c:p.colours[0];selectedSize=null;$('#product-quantity').value='1';$('#product-error').textContent='';$('#add-status').textContent='';$('#dialog-title').textContent=p.name;$('#detail-collection').textContent=`${p.collection} / ${p.type}`;$('#detail-price').textContent=money(p.price);$('#dialog-description').textContent=p.description;$('#fit-note').textContent=p.type==='Cargos'?(p.id==='wide-leg-cargo'?'wide leg':'relaxed taper'):'relaxed / oversized';$('#size-legend').textContent=p.type==='Cargos'?'Select waist size (inches)':'Select size';$('#size-options').innerHTML=p.sizes.map(s=>`<button type="button" data-size="${s}" aria-pressed="false">${s}</button>`).join('');$('#size-options').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{selectedSize=b.dataset.size;$('#size-options').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#product-error').textContent='';}));renderColours();if(!productDialog.open)productDialog.showModal();document.body.style.overflow='hidden';}
function renderColours(){const p=selected;$('#selected-colour').textContent=colours[selectedColour].name;showProductImage($('#detail-image'),p,selectedColour,`${p.name} in ${colours[selectedColour].name}`);$('#colour-options').innerHTML=p.colours.map(c=>`<button type="button" class="swatch" data-colour="${c}" style="--swatch:${colours[c].hex}" aria-label="${colours[c].name}" aria-pressed="${c===selectedColour}"></button>`).join('');$('#colour-options').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{selectedColour=b.dataset.colour;history.replaceState(null,'',`#product=${p.id}&colour=${selectedColour}`);renderColours();$('#colour-options').querySelector(`[data-colour="${selectedColour}"]`).focus();$('#add-status').textContent='';}));}
function renderBag(){saveBag();$('#bag-lines').innerHTML=bag.length?bag.map((l,i)=>{const p=products.find(p=>p.id===l.id);return `<article class="bag-line"><img src="${imageFor(p,l.colour)}" width="86" height="110" alt="${p.name}, ${colours[l.colour].name}"><div><h3>${p.name}</h3><p>${colours[l.colour].name} / Size ${l.size}</p><p class="line-price">${money(p.price*l.quantity)}</p><div class="line-controls"><button data-action="minus" data-index="${i}" aria-label="Decrease quantity of ${p.name}" ${l.quantity===1?'disabled':''}>−</button><span aria-label="Quantity">${l.quantity}</span><button data-action="plus" data-index="${i}" aria-label="Increase quantity of ${p.name}" ${l.quantity===10?'disabled':''}>+</button><button class="remove-line" data-action="remove" data-index="${i}" aria-label="Remove ${p.name}, ${colours[l.colour].name}, size ${l.size}">Remove</button></div></div></article>`;}).join(''):'<p class="empty-bag">Your bag is waiting for your point of view.<br>Explore the collection and add a piece.</p>';$('#bag-summary').hidden=!bag.length;$('#bag-subtotal').textContent=money(bag.reduce((n,l)=>n+products.find(p=>p.id===l.id).price*l.quantity,0));$('#checkout').disabled=!commerce.enabled||!bag.length;$('#checkout').textContent=commerce.enabled?'Continue to secure checkout':'Checkout opens at launch';$('#bag-lines').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.index),action=b.dataset.action;if(action==='remove')bag.splice(i,1);else bag[i].quantity=Math.max(1,Math.min(10,bag[i].quantity+(action==='plus'?1:-1)));renderBag();const next=$('#bag-lines').querySelector(`[data-index="${Math.min(i,bag.length-1)}"][data-action="${action}"]`);(next||$('.continue-shopping')).focus();}));}
function openBag(){if(productDialog.open)productDialog.close();renderBag();bagDialog.showModal();document.body.style.overflow='hidden';}
for(const dialog of [productDialog,bagDialog]){dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{if(!productDialog.open&&!bagDialog.open)document.body.style.overflow='';if(dialog===productDialog&&location.hash.startsWith('#product='))history.replaceState(null,'','#collection');});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});}
$('#add-to-bag').addEventListener('click',()=>{if(!selectedSize){$('#product-error').textContent='Choose your size first.';$('#size-options button').focus();return;}const quantity=Number($('#product-quantity').value);if(!Number.isInteger(quantity)||quantity<1||quantity>10){$('#product-error').textContent='Choose a quantity from 1 to 10.';return;}const line={id:selected.id,colour:selectedColour,size:selectedSize,quantity};const existing=bag.find(l=>key(l)===key(line));if(existing&&existing.quantity+quantity>10){$('#product-error').textContent='You can preview up to 10 of this size and colour in your bag.';return;}if(existing)existing.quantity+=quantity;else bag.push(line);saveBag();$('#product-error').textContent='';$('#add-status').textContent=`Added ${quantity} × ${selected.name}, ${colours[selectedColour].name}, size ${selectedSize}.`;});
$('#open-bag').addEventListener('click',openBag);$('#detail-bag').addEventListener('click',openBag);$('.continue-shopping').addEventListener('click',()=>{bagDialog.close();location.hash='collection';});$('#checkout').addEventListener('click',async()=>{if(!commerce.enabled)return;$('#checkout').disabled=true;$('#checkout-status').textContent='Opening secure checkout…';try{location.assign(await createCheckout(bag));}catch(e){$('#checkout-status').textContent=e.message;$('#checkout').disabled=false;}});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderCatalogue();}));$('#sort').addEventListener('change',e=>{sort=e.target.value;renderCatalogue();});const collectionNames=[...new Set(products.map(p=>p.collection))];
$('#collection-filter').replaceChildren(...['All collections',...collectionNames].map((name,i)=>{const option=document.createElement('option');option.value=i?name:'All';option.textContent=name;return option;}));
$('#collection-summary').textContent=collectionNames.join(' · ')+'. Make them your own.';
$('#collection-filter').addEventListener('change',e=>{collection=e.target.value;renderCatalogue();});
window.addEventListener('hashchange',route);renderCatalogue();saveBag();route();
// The bag is a non-authoritative, per-tab draft. Shopify owns prices, stock and orders at checkout.
import('./viewer.js').catch(()=>{$('#viewer-status').textContent='3D could not load. Product image shown instead.';$('.hero-stage').classList.add('model-unavailable');});

